// 「入力を整形」ノードから予約者情報を取得
const form = $('Normalize Input').first().json;

// フォームで選択された希望枠
const requestedSlotId = form.slot_id;

// 予約人数
const partySize = Number(form.party_size);

// 「時間枠を取得」から届いた全時間枠
const slots = $input.all()
  .map(item => item.json)
  .sort((a, b) => Number(a.slot_order) - Number(b.slot_order));

// 希望枠を探す
const requestedSlot = slots.find(
  slot => slot.slot_id === requestedSlotId
);

// 希望枠が存在しない場合
if (!requestedSlot) {
  return [{
    json: {
      name: form.name,
      email: form.email,
      party_size: partySize,

      requested_slot_id: requestedSlotId,
      requested_slot_label: null,

      assigned_slot_id: null,
      assigned_slot_label: null,

      available: false,
      reassigned: false,
      reason: '指定された時間枠が存在しません',

      capacity: 0,
      reserved_count: 0,
      new_reserved_count: 0,
      remaining: 0,
      slot_status: null,
    },
  }];
}

// 予約人数を確認
if (
  !Number.isInteger(partySize) ||
  partySize < 1 ||
  partySize > 5
) {
  return [{
    json: {
      name: form.name,
      email: form.email,
      party_size: partySize,

      requested_slot_id: requestedSlotId,
      requested_slot_label: requestedSlot.slot_label,

      assigned_slot_id: null,
      assigned_slot_label: null,

      available: false,
      reassigned: false,
      reason: '予約人数は1名から5名で入力してください',

      capacity: 0,
      reserved_count: 0,
      new_reserved_count: 0,
      remaining: 0,
      slot_status: null,
    },
  }];
}

// 希望枠以降で予約可能な時間枠を探す
const selectedSlot = slots.find(slot => {
  const capacity = Number(slot.capacity);
  const reservedCount = Number(slot.reserved_count);
  const remaining = capacity - reservedCount;

  return (
    Number(slot.slot_order) >= Number(requestedSlot.slot_order) &&
    slot.status === 'open' &&
    remaining >= partySize
  );
});

// 希望枠以降に空きがない場合
if (!selectedSlot) {
  return [{
    json: {
      name: form.name,
      email: form.email,
      party_size: partySize,

      requested_slot_id: requestedSlotId,
      requested_slot_label: requestedSlot.slot_label,

      assigned_slot_id: null,
      assigned_slot_label: null,

      available: false,
      reassigned: false,
      reason: '希望時間以降の枠はすべて満席です',

      capacity: Number(requestedSlot.capacity),
      reserved_count: Number(requestedSlot.reserved_count),
      new_reserved_count: Number(requestedSlot.reserved_count),
      remaining: Math.max(
        0,
        Number(requestedSlot.capacity) -
        Number(requestedSlot.reserved_count)
      ),
      slot_status: requestedSlot.status,
    },
  }];
}

// 確定枠の人数を計算
const capacity = Number(selectedSlot.capacity);
const reservedCount = Number(selectedSlot.reserved_count);
const newReservedCount = reservedCount + partySize;
const remaining = capacity - newReservedCount;

// 結果を後続ノードへ渡す
return [{
  json: {
    name: form.name,
    email: form.email,
    party_size: partySize,

    requested_slot_id: requestedSlotId,
    requested_slot_label: requestedSlot.slot_label,

    assigned_slot_id: selectedSlot.slot_id,
    assigned_slot_label: selectedSlot.slot_label,

    // 既存の後続ノードでも使えるように残す
    slot_id: selectedSlot.slot_id,
    slot_label: selectedSlot.slot_label,

    available: true,

    // 希望枠と確定枠が違うか
    reassigned: selectedSlot.slot_id !== requestedSlotId,

    capacity,
    reserved_count: reservedCount,
    new_reserved_count: newReservedCount,
    remaining,

    // 今回の予約で満席になったらclosed
    slot_status:
      newReservedCount >= capacity
        ? 'closed'
        : 'open',

    reason:
      selectedSlot.slot_id === requestedSlotId
        ? '希望時間枠で予約可能です'
        : '希望枠が満席のため次の空き枠へ変更しました',
  },
}];

