// Data Tableから取得した全時間枠
const slots = $input.all()
  .map(item => item.json)
  .sort((a, b) => Number(a.slot_order) - Number(b.slot_order));

if (slots.length === 0) {
  return [
    {
      json: {
        discord_message: '現在、時間枠の情報を取得できませんでした。'
      }
    }
  ];
}

const lines = slots.map(slot => {
  const capacity = Number(slot.capacity ?? 0);
  const reservedCount = Number(slot.reserved_count ?? 0);

  // マイナス表示を防止
  const available = Math.max(capacity - reservedCount, 0);

  if (slot.status === 'closed' || available === 0) {
    return `🔴 **${slot.slot_label}**｜満席`;
  }

  return `🟢 **${slot.slot_label}**｜残り **${available}名**`;
});

const openSlotCount = slots.filter(slot => {
  const capacity = Number(slot.capacity ?? 0);
  const reservedCount = Number(slot.reserved_count ?? 0);
  return slot.status === 'open' && capacity - reservedCount > 0;
}).length;

const message = [
  '## 📅 現在の予約空き状況',
  '',
  ...lines,
  '',
  `予約可能な時間枠：**${openSlotCount}枠**`,
  '',
  `最終更新：${new Date().toLocaleString('ja-JP', {
    timeZone: 'Asia/Tokyo'
  })}`
].join('\n');

return [
  {
    json: {
      discord_message: message
    }
  }
];

